$ErrorActionPreference='Stop'
[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
$self=[Diagnostics.Process]::GetCurrentProcess()
$self.PriorityClass='BelowNormal'
$self.ProcessorAffinity=[IntPtr]4
$start=[Diagnostics.ProcessStartInfo]::new()
$start.FileName='C:\Windows\System32\wsl.exe'
$start.UseShellExecute=$false
$start.CreateNoWindow=$true
$start.RedirectStandardOutput=$true
$start.RedirectStandardError=$true
foreach($item in @('--distribution','Ubuntu-22.04','--exec','/usr/bin/python3','-B','-c',"import base64;exec(base64.b64decode(''))")){[void]$start.ArgumentList.Add($item)}
$p=[Diagnostics.Process]::new();$p.StartInfo=$start;[void]$p.Start()
try{$p.PriorityClass='BelowNormal';$p.ProcessorAffinity=[IntPtr]4}catch{}
$errTask=$p.StandardError.ReadToEndAsync()
while(-not $p.StandardOutput.EndOfStream){[Console]::WriteLine($p.StandardOutput.ReadLine())}
$p.WaitForExit()
$err=$errTask.GetAwaiter().GetResult();$code=$p.ExitCode
$p.Dispose()
if($err){[Console]::Error.Write($err)}
if($code -ne 0){throw ('Pgroup controller exit '+$code+'; preserve original output')}
